package com.hbm.entity.mob.maskman;
import com.hbm.exposure.HbmExposure;import net.minecraft.ChatFormatting;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.*;import net.minecraft.stats.Stats;import net.minecraft.world.Difficulty;import net.minecraft.world.entity.MobSpawnType;import net.minecraft.world.level.levelgen.Heightmap;import net.neoforged.neoforge.event.EventHooks;
/** Actual BossSpawnHandler's maskman branch only; player's original eligible-seconds timer persists across logout but resets on death. */
public final class MaskManSpawn {
 private static final String TIMER="maskManTimer";
 public static void update(ServerLevel level){if(level.getGameTime()%20!=0||!MaskManConfig.ENABLED.get()||!level.dimensionType().natural()||level.getDifficulty()==Difficulty.PEACEFUL)return;var crystallizer=BuiltInRegistries.ITEM.get(ResourceLocation.parse("hbm:machine_crystallizer"));for(var player:level.players()){boolean stat=!MaskManConfig.REQUIRE_CRAFT_STAT.get()||player.getStats().getValue(Stats.ITEM_CRAFTED.get(crystallizer))>0||player.getStats().getValue(Stats.ITEM_USED.get(crystallizer))>0;boolean radiation=HbmExposure.radiation(player)>=MaskManConfig.MIN_RAD.get(),underground=!MaskManConfig.UNDERGROUND.get()||com.hbm.world.SourceWorldHeight.get(level,(int)Math.floor(player.getX()),(int)Math.floor(player.getZ()))>player.getY()+3;var data=player.getPersistentData();if(stat&&radiation&&underground){int timer=data.getInt(TIMER)+1;data.putInt(TIMER,timer);if(timer==MaskManConfig.DELAY.get()-60)player.sendSystemMessage(Component.translatable("message.hbm.maskman.near").withStyle(ChatFormatting.RED));if(timer>=MaskManConfig.DELAY.get()){data.putInt(TIMER,0);double x=player.getX()+level.random.nextGaussian()*20,z=player.getZ()+level.random.nextGaussian()*20,y=com.hbm.world.SourceWorldHeight.get(level,(int)Math.floor(x),(int)Math.floor(z));var mask=MaskManContent.MASKMAN.get().create(level);if(mask==null)throw new IllegalStateException("Actual maskman type factory returned null");mask.moveTo((float)x,(float)y,(float)z,level.random.nextFloat()*360,0);var check=new net.neoforged.neoforge.event.entity.living.MobSpawnEvent.PositionCheck(mask,level,MobSpawnType.EVENT,null);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(check);if(check.getResult()!=net.neoforged.neoforge.event.entity.living.MobSpawnEvent.PositionCheck.Result.FAIL){level.addFreshEntity(mask);EventHooks.finalizeMobSpawn(mask,level,level.getCurrentDifficultyAt(mask.blockPosition()),MobSpawnType.EVENT,null);player.sendSystemMessage(Component.translatable("message.hbm.maskman.spawned").withStyle(ChatFormatting.RED));}else player.sendSystemMessage(Component.translatable("message.hbm.maskman.failed").withStyle(ChatFormatting.BLUE));}}else data.putInt(TIMER,0);}}
 private MaskManSpawn(){}
}
